CREATE TABLE companies (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL);
CREATE TABLE users (id INT PRIMARY KEY, company_id INT NULL, name VARCHAR(100) NOT NULL);
CREATE TABLE user_company_memberships (user_id INT NOT NULL, company_id INT NOT NULL, is_active TINYINT NOT NULL DEFAULT 1, PRIMARY KEY(user_id,company_id));
CREATE TABLE customers (id INT PRIMARY KEY, company_id INT NOT NULL, name VARCHAR(150) NOT NULL, phone VARCHAR(20), credit_period_days INT DEFAULT 30, shipping_address TEXT, billing_address TEXT);
CREATE TABLE vendors (id INT PRIMARY KEY, company_id INT NOT NULL, name VARCHAR(150) NOT NULL, status VARCHAR(20) NULL);
CREATE TABLE products (id INT PRIMARY KEY, company_id INT NOT NULL, name VARCHAR(150) NOT NULL, stock DECIMAL(15,3) NOT NULL DEFAULT 0, mrp DECIMAL(10,2) NOT NULL DEFAULT 0, purchase_price DECIMAL(10,2) NOT NULL DEFAULT 0, gst DECIMAL(5,2) NOT NULL DEFAULT 18);
CREATE TABLE accounts (id INT AUTO_INCREMENT PRIMARY KEY, account_code VARCHAR(80), account_name VARCHAR(150) NOT NULL, account_type VARCHAR(40) NOT NULL, parent_account_id INT NULL, opening_balance DECIMAL(15,2) DEFAULT 0, balance_type VARCHAR(10), description VARCHAR(255), status TINYINT NOT NULL DEFAULT 1, company_id INT NOT NULL, UNIQUE KEY uq_accounts_company_code(company_id,account_code));
CREATE TABLE invoice_settings (company_id INT PRIMARY KEY, prefix VARCHAR(20), current_number INT DEFAULT 1);
CREATE TABLE financial_years (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(120), start_date DATE NOT NULL, end_date DATE NOT NULL, status ENUM('DRAFT','OPEN','RECONCILIATION','CLOSING','CLOSED','LOCKED') NOT NULL DEFAULT 'DRAFT', is_default TINYINT NOT NULL DEFAULT 0, source VARCHAR(40) NOT NULL DEFAULT 'TEST', created_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_fy_company_dates(company_id,start_date,end_date), UNIQUE KEY uq_fy_id_company(id,company_id));
CREATE TABLE financial_year_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, financial_year_id BIGINT UNSIGNED NOT NULL, event_type VARCHAR(40) NOT NULL);
CREATE TABLE invoices (id INT AUTO_INCREMENT PRIMARY KEY, request_id VARCHAR(80), company_id INT NOT NULL, financial_year_id BIGINT UNSIGNED NULL, created_by INT NOT NULL, invoice_number VARCHAR(50) NOT NULL, invoice_date DATE NOT NULL, invoice_type VARCHAR(10), customer_id INT NULL, customer_name VARCHAR(255) NOT NULL, customer_phone VARCHAR(20), cash_customer_name VARCHAR(255), cash_customer_mobile VARCHAR(20), credit_days INT, due_date DATE, shipping_address TEXT, subtotal DECIMAL(10,2) DEFAULT 0, discount_amount DECIMAL(12,2) DEFAULT 0, tax_amount DECIMAL(10,2) DEFAULT 0, cgst DECIMAL(10,2) DEFAULT 0, sgst DECIMAL(10,2) DEFAULT 0, igst DECIMAL(10,2) DEFAULT 0, overall_discount_type VARCHAR(10), overall_discount_value DECIMAL(12,2) DEFAULT 0, overall_discount_amount DECIMAL(12,2) DEFAULT 0, additional_discount_type VARCHAR(10), additional_discount_value DECIMAL(12,2) DEFAULT 0, additional_discount_amount DECIMAL(12,2) DEFAULT 0, round_off_amount DECIMAL(12,2) DEFAULT 0, total_amount DECIMAL(10,2) NOT NULL, status VARCHAR(30) DEFAULT 'pending', payment_status VARCHAR(12) NULL, UNIQUE KEY uq_invoices_company_request(company_id,request_id), INDEX idx_invoices_company_fy(company_id,financial_year_id), CONSTRAINT fk_invoices_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
CREATE TABLE invoice_items (id INT AUTO_INCREMENT PRIMARY KEY, invoice_id INT NOT NULL, company_id INT NOT NULL, product_id INT, item_name VARCHAR(255), description TEXT, quantity DECIMAL(15,3), unit VARCHAR(30), serial_numbers_json JSON, batch_no VARCHAR(100), manufactured_date DATE, expiry_date DATE, unit_price DECIMAL(10,2), mrp DECIMAL(10,2) DEFAULT 0, discount_type VARCHAR(10) DEFAULT 'AMOUNT', discount_value DECIMAL(12,2) DEFAULT 0, discount_amount DECIMAL(12,2) DEFAULT 0, total_price DECIMAL(10,2), gst_rate DECIMAL(5,2));
CREATE TABLE receipt_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, receipt_number VARCHAR(80) NOT NULL, receipt_date DATE NOT NULL, receipt_type VARCHAR(20) NOT NULL, customer_id INT, invoice_id INT, received_in_account_id INT NOT NULL, received_from_account_id INT NOT NULL, amount DECIMAL(15,2) NOT NULL, payment_mode VARCHAR(40) NOT NULL, reference_number VARCHAR(120), narration VARCHAR(500), company_id INT NOT NULL, created_by INT NOT NULL, idempotency_key VARCHAR(80) NOT NULL, journal_entry_id BIGINT, payment_id BIGINT, advance_id BIGINT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_receipt_company_number(company_id,receipt_number), UNIQUE KEY uq_receipt_company_idempotency(company_id,idempotency_key));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, invoice_id INT NOT NULL, company_id INT NOT NULL, financial_year_id BIGINT UNSIGNED NULL, amount DECIMAL(10,2) NOT NULL, payment_date DATE NOT NULL, payment_method VARCHAR(40), reference_number VARCHAR(100), receipt_entry_id BIGINT UNSIGNED, INDEX idx_payments_company_fy(company_id,financial_year_id), CONSTRAINT fk_payments_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
CREATE TABLE bills (id INT AUTO_INCREMENT PRIMARY KEY, vendor_id INT, bill_number VARCHAR(50), bill_date DATE, due_date DATE, total_amount DECIMAL(10,2), paid_amount DECIMAL(15,2) DEFAULT 0, due_amount DECIMAL(15,2) DEFAULT 0, status VARCHAR(30) DEFAULT 'Unpaid', company_id INT NOT NULL, financial_year_id BIGINT UNSIGNED NULL, INDEX idx_bills_company_fy(company_id,financial_year_id), CONSTRAINT fk_bills_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
CREATE TABLE bill_items (id INT AUTO_INCREMENT PRIMARY KEY, bill_id INT, product_id INT, product_name VARCHAR(255), quantity DECIMAL(15,3), price DECIMAL(10,2), mrp DECIMAL(10,2), total DECIMAL(10,2), gst_percent DECIMAL(5,2), cgst DECIMAL(10,2), sgst DECIMAL(10,2));
CREATE TABLE vendor_payments (id INT AUTO_INCREMENT PRIMARY KEY, vendor_id INT, bill_id INT, amount DECIMAL(10,2), payment_date DATE, payment_method VARCHAR(50), paid_from_account_id INT, reference_number VARCHAR(120), notes TEXT, company_id INT, financial_year_id BIGINT UNSIGNED NULL, created_by INT, journal_entry_id BIGINT, idempotency_key VARCHAR(100), status VARCHAR(20) DEFAULT 'SUCCESS', INDEX idx_vendor_payments_company_fy(company_id,financial_year_id), CONSTRAINT fk_vendor_payments_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
CREATE TABLE expenses (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255), category VARCHAR(100), amount DECIMAL(10,2), expense_date DATE, notes TEXT, company_id INT, financial_year_id BIGINT UNSIGNED NULL, INDEX idx_expenses_company_fy(company_id,financial_year_id), CONSTRAINT fk_expenses_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
CREATE TABLE journal_entries (id BIGINT AUTO_INCREMENT PRIMARY KEY, journal_no VARCHAR(50), journal_date DATE, narration TEXT, total_debit DECIMAL(15,2), total_credit DECIMAL(15,2), created_by INT, status TINYINT DEFAULT 1, company_id INT NOT NULL, financial_year_id BIGINT UNSIGNED NULL, vendor_id INT, source_type VARCHAR(50), source_id BIGINT, INDEX idx_journal_entries_company_fy(company_id,financial_year_id), CONSTRAINT fk_journal_entries_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
CREATE TABLE journal_entry_details (id BIGINT AUTO_INCREMENT PRIMARY KEY, journal_entry_id BIGINT NOT NULL, account_id INT NOT NULL, debit DECIMAL(15,2) DEFAULT 0, credit DECIMAL(15,2) DEFAULT 0, description VARCHAR(255), CONSTRAINT fk_jed_journal FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id), CONSTRAINT fk_jed_account FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE ledger_entries (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, financial_year_id BIGINT UNSIGNED NULL, entity_type VARCHAR(50), entity_id INT, reference_type VARCHAR(50), reference_id INT, debit DECIMAL(10,2), credit DECIMAL(10,2), transaction_date DATE, INDEX idx_ledger_entries_company_fy(company_id,financial_year_id), CONSTRAINT fk_ledger_entries_company_fy FOREIGN KEY(financial_year_id,company_id) REFERENCES financial_years(id,company_id));
